public class CharCodesTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("codeOf('A')", 65, CharCodes.codeOf('A'));
        check("codeOf('z')", 122, CharCodes.codeOf('z'));
        check("codeOf('0')", 48, CharCodes.codeOf('0'));
        check("codeOf(' ')", 32, CharCodes.codeOf(' '));
        check("charOf(65)", 'A', CharCodes.charOf(65));
        check("charOf(122)", 'z', CharCodes.charOf(122));
        check("charOf(97)", 'a', CharCodes.charOf(97));
        check("round trip codeOf(charOf(77))", 77, CharCodes.codeOf(CharCodes.charOf(77)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

